<?php require_once __DIR__.'/../config/config.php';role_required(['admin']);$pageTitle='Reports';$rows=db()->query('SELECT status,COUNT(*) n FROM manuscripts GROUP BY status ORDER BY n DESC')->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">Editorial Reports</h1><div class="panel"><table><tr><th>Status</th><th>Count</th></tr><?php foreach($rows as $r):?><tr><td><?=e(slabel($r['status']))?></td><td><?=e($r['n'])?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>